SELECT dc.*, f.public_id AS source_document_public_id, f.file_name AS source_file_name, f.type AS source_file_type, k.public_id AS source_knowledge_public_id, k.name AS source_knowledge_name FROM document_chunk dc JOIN knowledge k ON k.id = dc.knowledge_id AND k.tenant_id = dc.tenant_id JOIN file f ON f.id = dc.file_id AND f.tenant_id = dc.tenant_id JOIN knowledge_file kf ON kf.file_id = dc.file_id AND kf.knowledge_id = dc.knowledge_id AND kf.tenant_id = dc.tenant_id WHERE dc.tenant_id = #{tenantId} AND f.tenant_id = #{tenantId} AND kf.tenant_id = #{tenantId} AND dc.status = 2 AND f.status = 1 AND dc.content IS NOT NULL AND dc.content ~ U&'[^\0009-\000D\001C-\0020\00A0\1680\2000-\200A\2028\2029\202F\205F\3000]' AND dc.index_content IS NOT NULL AND dc.index_content ~ '[^[:space:]]' AND dc.knowledge_id IN
#{knowledgeId}
AND kf.knowledge_id IN
#{knowledgeId}
AND dc.public_id IN
#{publicId,jdbcType=OTHER,typeHandler=com.starsea.ai.auth.UuidTypeHandler}

